const DEFAULT_CURRENCY_DECIMALS=2,CURRENCY_DECIMALS={BHD:3,BIF:0,BYR:0,CLF:4,CLP:0,DJF:0,GNF:0,IQD:3,ISK:0,JOD:3,JPY:0,KMF:0,KRW:0,KWD:3,LYD:3,MRO:5,OMR:3,PYG:0,RWF:0,TND:3,UGX:0,UYI:0,UYW:4,VND:0,VUV:0,XAF:0,XAG:0,XAU:0,XBA:0,XBB:0,XBC:0,XBD:0,XDR:0,XOF:0,XPD:0,XPF:0,XPT:0,XSU:0,XTS:0,XUA:0};export function convertMoneyToMinorUnits(t,e){const a=CURRENCY_DECIMALS[e.toUpperCase()]??2,n=Math.pow(10,a);if(!t||!t.trim())return null;const r=t.trim().split(/[^0-9]/).filter(Boolean);if(0===r.length)return null;const o=r[r.length-1]??"";let s,c;a>0&&r.length>1&&o.length<=a?(c=o,s=r.slice(0,-1).join("")):(s=r.join(""),c="");const i=parseInt(s,10);if(isNaN(i))return null;let _=0;if(a>0&&c){const t=c.length;_=parseInt(c,10)||0,_*=Math.pow(10,a-t)}return i*n+_}function formatCents(t,e,a,n,r){const o=(t/r).toFixed(n);let[s,c]=o.split(".");return s||(s="0"),c||(c=""),s=s.replace(/\d(?=(\d\d\d)+(?!\d))/g,t=>t+e),n<=0?s:s+a+c.padEnd(n,"0")}export function formatMoney(t,e,a){const n=CURRENCY_DECIMALS[a.toUpperCase()]??2,r=Math.pow(10,n);return e.replace(/{{\s*(\w+)\s*}}/g,(e,o)=>{if("string"!=typeof o)return"";if("currency"===o)return a;let s=",",c=".",i=n;switch(o){case"amount":default:break;case"amount_no_decimals":i=0;break;case"amount_with_comma_separator":s=".",c=",";break;case"amount_no_decimals_with_comma_separator":s=".",i=0;break;case"amount_no_decimals_with_space_separator":s=" ",i=0;break;case"amount_with_space_separator":s=" ",c=",";break;case"amount_with_period_and_space_separator":s=" ",c=".";break;case"amount_with_apostrophe_separator":s="'",c="."}return formatCents(t,s,c,i,r)})}